<?php
declare(strict_types=1); require __DIR__ . '/../../config/database.php'; require_once __DIR__ . '/../Services/Auth/auth.php'; require_once __DIR__ . '/../Utils/xlsx-builder.php'; wajibRole('pic','koordinator','manager','direktur','admin','superadmin');
$where=roleOperasional()?'d.department_id = '.(int)departmentIdPengguna():'1=1'; $kolom=['id'=>['ID','d.id'],'karyawan'=>['Nama Karyawan','k.employee_name'],'nominal'=>['Nominal','d.nominal'],'deskripsi'=>['Keterangan','d.deskripsi'],'status'=>['Status','d.status'],'dibuat'=>['Waktu Pengajuan','d.created_at']]; $pilihan=$_GET['kolom']??array_keys($kolom); if(!is_array($pilihan))$pilihan=[$pilihan]; $pilihan=array_values(array_intersect(array_keys($kolom),$pilihan)); if(!$pilihan)$pilihan=array_keys($kolom); $sort=$_GET['sort_export']??'dibuat'; if(!isset($kolom[$sort]))$sort='dibuat'; $arah=strtoupper($_GET['arah_export']??'DESC'); if(!in_array($arah,['ASC','DESC'],true))$arah='DESC'; $batas=(string)($_GET['batas_export']??'semua'); $limit=$batas==='semua'?'':' LIMIT '.max(1,min(10000,(int)$batas)); $q=mysqli_query($conn,"SELECT d.id,k.employee_name,d.nominal,d.deskripsi,d.status,d.created_at,COALESCE(pe.role, (SELECT u2.role FROM denda_approvals a2 INNER JOIN users u2 ON u2.id=a2.approver_user_id WHERE a2.denda_id=d.id AND a2.status='approved' ORDER BY a2.decided_at DESC LIMIT 1)) AS role_pemroses FROM denda_reports d LEFT JOIN users pe ON pe.id=d.diproses_oleh_user_id INNER JOIN karyawan k ON k.id=d.karyawan_id WHERE {$where} ORDER BY {$kolom[$sort][1]} {$arah},d.id DESC{$limit}"); $rows=[]; while($q&&($r=mysqli_fetch_assoc($q))){$v=['id'=>$r['id'],'karyawan'=>$r['employee_name'],'nominal'=>'Rp '.number_format((float)$r['nominal'],0,',','.'),'deskripsi'=>$r['deskripsi'],'status'=>(in_array($r['status'],['disetujui','selesai'],true)?'Disetujui '.labelRole((string)($r['role_pemroses']??'manager')):ucwords(str_replace('_',' ',$r['status']))),'dibuat'=>$r['created_at']];$rows[]=array_map(fn($k)=>$v[$k],$pilihan);} $headers=array_map(fn($k)=>$kolom[$k][0],$pilihan); if(isset($_GET['download']))unduhSpreadsheetXlsx('laporan-denda-'.date('Y-m-d'),'Denda',$headers,$rows); $judulHalaman='Export Denda';$subjudulHalaman='Pratinjau data denda sebelum diunduh.';$halamanAktif='denda';require __DIR__ . '/../../resources/views/layouts/atas.php'; ?>
<section class="form-card export-options-card"><div class="form-card-header"><h2>Opsi Export Denda</h2><p><?= count($rows); ?> data akan diekspor.</p></div><div class="form-body"><form method="GET" class="export-options-form"><div class="form-group"><label>Jumlah data</label><select name="batas_export"><option value="semua">Semua data</option><?php foreach([10,25,50,100] as $n): ?><option value="<?=$n;?>" <?=$batas===(string)$n?'selected':'';?>>Maksimal <?=$n;?> data</option><?php endforeach;?></select></div><div class="form-group"><label>Urutkan berdasarkan</label><select name="sort_export"><?php foreach($kolom as $k=>$v): ?><option value="<?=$k;?>" <?=$sort===$k?'selected':'';?>><?=htmlspecialchars($v[0]);?></option><?php endforeach;?></select></div><div class="form-group"><label>Arah urutan</label><select name="arah_export"><option value="DESC" <?=$arah==='DESC'?'selected':'';?>>Turun</option><option value="ASC" <?=$arah==='ASC'?'selected':'';?>>Naik</option></select></div><fieldset class="export-columns-fieldset"><legend>Kolom yang diekspor</legend><?php foreach($kolom as $k=>$v): ?><label><input type="checkbox" name="kolom[]" value="<?=$k;?>" <?=in_array($k,$pilihan,true)?'checked':'';?>> <?=htmlspecialchars($v[0]);?></label><?php endforeach;?></fieldset><div class="form-actions"><a class="btn btn-secondary" href="denda.php">Batal</a><button class="btn btn-primary" name="download" value="1">Unduh Excel</button></div></form></div></section><section class="data-card export-preview-card"><div class="data-card-header"><h2>Pratinjau Export Denda</h2></div><div class="table-wrapper"><table><thead><tr><?php foreach($headers as $h):?><th><?=htmlspecialchars($h);?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($r as $cell):?><td><?=nl2br(htmlspecialchars((string)$cell));?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></section><script>document.querySelectorAll('.export-options-form select,.export-options-form input[type="checkbox"]').forEach(e=>e.addEventListener('change',()=>{const f=e.form;if(e.type==='checkbox'&&!f.querySelector('input[name="kolom[]"]:checked')){e.checked=true;return;}f.querySelector('[name="download"]')?.removeAttribute('name');f.submit();}));</script><?php require __DIR__ . '/../../resources/views/layouts/bawah.php'; ?>
